from pathlib import Path
import json,re
R=Path('design-study'); out=[]
def add(id,title,body,notes='',image=None,urls=[],kind='text',section='Foundations'):
 out.append(dict(id=id,title=title,body=body,notes=notes,image=image,source_urls=urls,kind=kind,section=section))
add('cover','A field guide\nto expressive design',['Visual styles, logo craft and brand systems','Living study edition 1.0 • 8 September 2026'],kind='cover')
add('map','How to use this field guide',['Browse the visual atlas to learn the vocabulary.','Read the case studies to see how decisions work together.','Use the exercises and templates for future design reviews.'], 'The slide canvas carries the main lesson. Speaker notes preserve context, source URLs and open questions. This is a learning library, not an approved Levarum identity. New references can be added using the template near the end. Keep the same deck as the working artifact and use Google Slides version history for substantial revisions.')
add('evidence','Four kinds of evidence',['Observed: visible in an inspected image or page.','Documented: a source describes the process or rationale.','Interpretation: our explanation or design hypothesis.','Tested: a named check with recorded conditions and results.'],'An attractive reference does not establish usability, recall or sales. Source captions can establish a creator’s intent without proving an audience response. A screenshot may show a texture without identifying the production process. The notes flag access gaps and original-artwork attribution limits. All four labels are useful, but they answer different questions.')
add('questions','Five questions for looking closely',['What attracts attention first? What appears related?','Which cues create the apparent material?','Which parts carry information, and which create atmosphere?','What survives when decorative effects disappear?'],'These questions form our teaching method. They are not a validated scoring rubric. Describe relationships such as scale, contrast, proximity, edge or lighting before assigning a style adjective. The answers turn an instinctive preference into something that can be developed and compared.')
add('atlas-cover','The visual atlas',['Ten labels. Several kinds of design knowledge.'],kind='divider',section='Visual atlas')
add('atlas-map','The names describe different things',['Risograph names a printing technology.','Gzhel names a regional ceramic tradition.','Austurbane is an attributed contemporary classification.','Other labels describe visual impressions or informal hybrids.'],'The names are useful entry points, not equivalent historical movements. The supplied overview preserves the wording used in the social post. It cannot establish that every pictured artist used the same label. Denny Kurien’s matching TikTok post was found and partially inspected. Original artwork credits remain incomplete.','../references/09-overview.jpeg',['https://www.tiktok.com/@denny.kurien/video/7680157545746418964'],kind='portrait',section='Visual atlas')
styles=[
('riso','Risograph','01-risograph.jpeg',['Separated spot colors create a layered composition.','Transparent overlaps introduce a third color relationship.','Texture can coexist with precise information.'],'A physical Risograph print uses stencil duplication, color separations and spot inks. PageMasters describes halftones, ink drums, registration and trapping. The poster screenshot suggests overprinting but cannot verify its physical production. RISO’s history distinguishes a 1958 precursor from 1980 models. Study the arrangement before imitating grain. Digital artwork should be described as Riso-inspired when no physical print exists.',['https://www.pagemasters.co/risograph','https://risottostudio.com/pages/advanced-print-setup','https://www.riso.co.jp/english/product/digital_dup/history/index.html']),
('clay','Claymorphism','02-claymorphism.jpeg',['Rounded edges and coordinated light suggest touch.','The reference combines fins, folds and glossy volumes.','A consistent material can connect different ideas.'],'The supplied Simplicity21 reference contains blue fins, green folds, coral cylinders and orange rounded forms. The matching portfolio credits Kyungtae Kim and Toss Design. Five objects represent the conference title and four themes. This connects visual form to content. Claymorphism is an informal label, not proof of a particular 3D process. A soft object used as illustration should not be confused with an interactive control.',['https://www.behance.net/gallery/127686975/Simplicity-21','https://microsoft.design/articles/an-emoji-for-your-thoughts-2/']),
('organic','Organic Tech','03-organic-tech.jpeg',['Porous, tufted forms surround a plain information card.','Biological complexity contrasts with precise typography.','The subject should connect to a real idea.'],'The observed contrast between intricate surface and restrained information creates much of this reference’s character. Organic need not mean green or environmental. Scale can shift a form from friendly to microscopic or unsettling. Nature-like appearance cannot substantiate environmental benefit. The original crop’s authorship remains unresolved. Cartier’s Farinart is an adjacent documented case using 3D grain forms tied to agriculture, rather than proof that the original artist used the label Organic Tech.',['https://agencecartier.com/en/projects/farinart-a-new-identity-crops-up/']),
('dirty','Dirty Gradients','04-dirty-gradients.jpeg',['Broad color transitions create atmosphere.','Muted mixing and irregular texture change the surface.','A quiet region helps the words retain priority.'],'Dirty is a loose descriptor for noise, uneven density, desaturation or irregular boundaries. The screenshot supports broad color transitions and restrained composition. Its exact grain method is unverified. Pentagram’s Intrinsic offers an adjacent example in which gradient echoes represent possible future robot positions. That source does not label its project Dirty Gradients. Meaning can come from behavior rather than an effect pasted onto every section.',['https://www.pentagram.com/work/intrinsic']),
('austurbane','Austurbane','05-austurbane.jpeg',['Restrained color and fine serif titles set a quiet rhythm.','Overlapping objects create depth and directional tension.','Lighting and materials contribute as much as palette.'],'CARI credits Alex Edwards with the label, combining austere and urbane. Its account includes generous space, natural materials, staged photography and dramatic shadows. This particular screenshot teaches angle, overlap and restraint. Beige and a serif do not guarantee sophistication. Compare the same objects under hard and diffuse light to isolate how lighting changes a composition. The pictured packaging’s creator remains unverified.',['https://cari.institute/aesthetics/austurbane']),
('brutal','Clean Girl Brutalism','06-clean-girl-brutalism.jpeg',['A heavy title anchors the upper edge.','A large quiet field separates it from compact information.','One saturated pink block carries strong visual weight.'],'The exact compound label’s origin and definition were not established. Architectural Brutalism and CARI’s Nu-Brutalism are related research contexts, not evidence for a single formal movement with this name. The useful observations are the heavy AGNI lettering, white space, edge rule and asymmetrical information. Sparse composition must still preserve useful labels and controls when translated to a website.',['https://cari.institute/aesthetics/nu-brutalism','https://www.riba.org/explore/riba-collections/architectural-styles/brutalism-movement/']),
('spray','Spray','07-spray.jpeg',['Blue gestural marks carry personality.','Small black typesetting carries product facts.','The arrangement stays organized while the marks vary.'],'A spray vocabulary can suggest play, workshop markings, street culture or military stencils depending on context. The supplied coffee package uses loose lettering and drawings. Pentagram’s American Weed Co. uses a different stencil language rooted in the founders’ context. Surface resemblance does not establish a shared meaning. Preserve legibility in critical information and investigate original authorship rather than crediting a repost account as the artist.',['https://www.pentagram.com/work/american-weed-co']),
('gzhel','Gzhel and the attribution question','08-gzhel.jpeg',['Cobalt-on-white can carry rhythm through tone and scale.','Repeated motifs and open space shape a pattern.','The LOEWE bag’s Gzhel attribution remains unverified.'],'The national Russian commission for UNESCO describes a regional ceramic history and twentieth-century revival involving Alexander Saltykov and Natalia Bessarabova. This is not evidence of a UNESCO heritage designation. The supplied LOEWE image shows blue birds and foliage in a tiled arrangement. The De Morgan Foundation documents another LOEWE collaboration, but it has not been matched to this exact bag. Preserve the uncertainty rather than relabel the asset. Study tonal brushwork and spacing as mechanisms.',['https://unesco.ru/en/news/gjel37/','https://farfor-gzhel.com/en/the-award-at-home-in-the-nomination-design-and-craft/','https://www.demorgan.org.uk/de-morgan-x-loewe-autumn-winter-2019/'])]
for id,t,img,b,n,u in styles:add(id,t,b,n,'../references/'+img,u,'portrait','Visual atlas')
add('iridescence','Holographic iridescence',['Changing highlights suggest a responsive material.','Reflection, geometry and lighting work together.','A static rainbow fill cannot establish holography.'],'Only the small overview tile was supplied for this label. Its object, maker and production method are unknown. 3M’s Dichroic DF Chill provides a documented physical comparison: apparent colors vary with viewing angle and with reflected versus transmitted light. Use a still image where it conveys the effect adequately. This terminology lesson distinguishes material behavior from a loose aesthetic description.',urls=['https://www.3m.com/3M/en_US/p/d/v000096543/'],section='Visual atlas')
add('asian','Cultural references need specific context',['The overview shows a dense frame and saturated contrast.','A maker, place and date are more useful than a broad label.','Lettering and motifs carry meanings beyond appearance.'],'Asian Chic has documented usage in Leshkowich and Jones’s 2003 fashion scholarship. That does not establish one graphic-design movement or the provenance of the supplied thumbnail. Their Vietnam and Indonesia examples show that meaning depends on who makes, circulates and interprets an object. A V&A account of chinoiserie is a separate historical comparison. The source resolution is insufficient to identify script or maker. Use an attributable object whenever possible.',urls=['https://www.colorado.edu/anthropology/sites/default/files/attached-files/5leshkowichjonesft.pdf','https://www.vam.ac.uk/articles/chinoiserie-an-introduction'],section='Visual atlas')
add('combining','Combining styles by assigning roles',['Typography and spacing organize the information.','One material family gives imagery a shared character.','Color creates atmosphere or carries a defined meaning.','A gesture supplies emphasis where it is useful.'],'This is our design heuristic, not a universal formula. Organic geometry could share one iridescent material without requiring every section to contain fur, chrome, clay and spray. The question is whether the effects compete for attention or serve distinct purposes. Play Studio’s Adobe MAX project provides an adjacent documented example of an organizing lens, core colors and varied artwork, including human-directed generative collage.',urls=['https://play.studio/work/adobe-max'],section='Visual atlas')
add('craft-cover','Logo craft and brand systems',['How specific decisions become a recognizable family.'],kind='divider',section='Logo craft')
brand=json.loads((R/'slides-content-brand.json').read_text())
for x in brand:x.update(kind='text',section='Logo craft');out.append(x)
# Case-study visuals remain source media, never recreated.
next(x for x in out if x['id']=='brand-07').update(image='assets/Anthropic_ClaudePage.jpg',kind='landscape')
add('anthropic-foundations','Anthropic’s foundations',['Warm color supports both communication and interface use.','Styrene and Tiempos bring different typographic voices.','The full system includes more than the logo.'],'Geist’s historical case study describes the relationship between human values and technical craft. These primary project visuals show its published palette and typography. They are examples from the case study, not a specification for current Anthropic products. Audience trust and commercial effectiveness have not been measured by this study.',image='assets/Anthropic_ColorPalette.svg',urls=['https://geist.co/work/anthropic'],kind='landscape',section='Brand systems')
add('anthropic-typography','Typography as a brand voice',['Letterforms set tone before decorative imagery appears.','A pairing needs clear roles for headings and reading text.','Actual size, spacing and context determine the result.'],'This is Geist’s published Anthropic typography specimen. Its account names Commercial Type’s Styrene and Klim’s Tiempos. Our transferable question is how type families divide the work across an interface, article and campaign. The same font can feel different when its size, weight, line length or spacing changes. The specimen does not approve these fonts for Levarum.',image='assets/Anthropic_Typography.svg',urls=['https://geist.co/work/anthropic'],kind='landscape',section='Brand systems')
add('anthropic-application','A system across repeated content',['Repeated content needs a stable information hierarchy.','Illustration can vary within that stable structure.','Guidelines make future choices easier to coordinate.'],'The source image shows article tiles in Geist’s Anthropic case study. Treat it as a historical project application. Compare recurring typography and layout with the varied subject matter. A useful visual system tells future makers which elements are fixed and which can vary. It does not require every page to repeat an identical composition.',image='assets/Anthropic_ArticleTiles.png',urls=['https://geist.co/work/anthropic'],kind='landscape',section='Brand systems')
add('web-cover','Design in use',['Reading, motion and smaller screens change the brief.'],kind='divider',section='Design in use')
ux=json.loads((R/'slides-content-ux.json').read_text())
for x in ux:x.update(kind='text',section='Design in use');out.append(x)
add('native-toolkit','Implementation choices in Squarespace',['Native settings: verify the current documented editor path.','Authored assets: retain originals and inspect exported crops.','Custom code or external services: record dependencies and rollback.','Test the result on the actual private site.'],'This slide is a future implementation checklist, not a feature audit. The current lesson does not verify native support for a particular effect, plan, font or integration. Before a build batch, identify whether the feature is native, an account dependency, an extension, custom code or an external service. Purchases, provider commitments, DNS, sharing and publication remain subject to specific approval. Keep a known-good version and undo route. No website implementation occurs during creation of this presentation.',section='Design in use')
add('workshop-cover','A repeatable design workshop',['Shared language makes the next decision easier.'],kind='divider',section='Workshop')
add('exercise-material','Exercise: material, spacing and grain',['Compare bundled material treatments while holding shapes still.','Change title-to-description spacing and observe grouping.','Vary grain strength over fixed text and a fixed gradient.'],'The companion study book implements these three exercises. The material selector changes several coordinated cues, so it is not a single-variable causal test. Spacing and grain exercises change a more focused variable. Record what the viewer notices without converting preference into an accessibility or conversion score. Motion remains a proposed later exercise. Download the HTML from the saved library and open it in a browser for interactive use.',urls=['https://drive.google.com/file/d/1-Xuq7o32ZkGV8pxPG61T45pqlr-okEV3/view'],section='Workshop')
add('reference-template','New reference template',['Reference title, creator, date and source URL','Screenshot and the specific detail to inspect','Observed mechanism and possible use','Unknowns, evidence status and next question'],'Duplicate this slide when adding a reference. Replace the prompts with source-specific content. Add full image attribution, the date accessed and any restrictions or failed retrievals to the notes. Separate the original artist from a curator or repost account. A reference can be inspiring while its provenance remains incomplete. Keep approved project decisions elsewhere so inclusion in this library is never mistaken for approval.',section='Workshop')
add('decision-template','Design decision template',['Requirement and intended audience','Alternatives compared under the same conditions','Choice, rationale and remaining uncertainty','Test evidence, owner, date and rollback route'],'Duplicate this page when a design decision is actually made. Identify what the user approved and the evidence behind it. Record proposed tests separately from completed tests. Retain rejected alternatives only when they explain a useful tradeoff. For Levarum, link the corresponding Sheet decision and session entry. This template contains no pending request for immediate art direction.',section='Workshop')
add('levarum','Questions to carry into Levarum',['Which feeling supports what the service actually does?','Which visual detail could become recognizably ours?','Where should expression appear, and where should reading lead?','What remains convincing without motion or decoration?'],'The user requested deeper study before a logo or website direction. These open questions preserve that sequence. The earlier palette, logo and style proposals do not become approved because they appear in the research history. A future concept comparison should use the same content and requirements, then inspect mobile, accessibility and performance. Keep private Levarum decisions separate from reusable methods.',section='Workshop')
add('maintenance','Keeping this library alive',['Keep this Google Slides deck as the working master.','Add source dates and evidence status when a lesson changes.','Use named versions for substantial revisions.','Maintain a short change log and a list of open questions.'],'Suggested maintenance method: add new references beside the relevant subject, update the index and source list, and append a dated entry explaining what changed and why. Recheck a source when its freshness matters to a decision. Saved knowledge supports later retrieval and discussion. It does not retrain the underlying model or guarantee automatic recall. The deck should be linked from the project’s working Sheet and remain private unless the owner approves otherwise.',section='Living library')
add('agents','Research contributors and training',['Three agents studied history, materials and perception.','Their sources and inspection limits are the verifiable record.','Role assignments do not imply separate specialist training.','Saving a library provides reusable context.'],'The agents used the same underlying model with distinct research briefs. OpenAI describes development data as including public internet information, partnerships and information supplied or generated by users, trainers and researchers. We do not have an itemized training bibliography, and cannot claim that a particular book or designer appeared in training. The notes identify the sources actually retrieved in this project. This gives us a durable basis for future review without implying model-weight retraining.',urls=['https://openai.com/policies/how-chatgpt-and-our-foundation-models-are-developed/'],section='Living library')
add('log','Edition history and open questions',['1.0 / 8 September 2026: first consolidated teaching deck.','Source artwork attribution remains incomplete for several reel images.','Lucy’s Bluey critique was sampled, not fully transcribed.','Audience response and Levarum implementation remain untested.'],'The initial edition consolidates six saved research chapters, original reference screenshots, agent teaching notes and source-specific observations. The Signals argument comes from the user’s supplied transcript. TBWA and Geist corroborate selected process claims, while broader brain and trust assertions remain unverified. Future entries should record a date, change, source and affected slide. The primary source library remains linked below.',urls=['https://drive.google.com/drive/folders/1CtjBy4KKutNKf97jToAocSG5_M6aGJVq'],section='Living library')
(R/'presentation/build/content.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
print('slides',len(out))
